import 'package:flutter_test/flutter_test.dart';
import 'package:metzgerapp/core/calculations.dart';
import 'package:metzgerapp/core/types.dart';
import 'package:metzgerapp/core/seed.dart';

void main(){
  test('Massenumrechnung und Einheitenprüfung',(){expect(convert(1,'kg','g'),1000);expect(convert(1,'g','mg'),1000);expect(convert(30,'min','h'),.5);expect(convert(1,'kg','l'),isNull);expect(lineCost({'quantity':30,'unit':'g','buyPrice':18,'buyQuantity':500,'buyUnit':'g'}),closeTo(1.08,1e-10));});
  test('Gewinn, Marge und Aufschlag unterscheiden sich',(){final c=Calculation(lines:[{'quantity':1,'unit':'Pauschale','buyPrice':100,'buyQuantity':1,'buyUnit':'Pauschale'}],inputKg:15,lossPercent:20,salePriceNet:14,taxPercent:7,targetMargin:40,soldKg:5,pieces:24);expect(c.outputKg,12);expect(c.costKg,closeTo(8.33333,.0001));expect(c.profit,68);expect(c.margin,closeTo(40.47619,.0001));expect(c.markup,68);expect(c.grossPrice,closeTo(14.98,.0001));expect(c.actualRevenue,70);expect(c.actualBalance,-30);expect(c.costPiece,closeTo(4.16667,.0001));expect(c.targetPrice,closeTo(13.88889,.0001));});
  test('Fehlende Kosten und ungültige Ausbeute liefern keinen Gewinn',(){final c=Calculation(lines:[{'quantity':1,'unit':'kg','buyQuantity':1,'buyUnit':'kg'}],inputKg:1,lossPercent:100,salePriceNet:10);expect(c.cost,isNull);expect(c.outputKg,isNull);expect(c.profit,isNull);});
  test('BEFFE und gewichtete Rohmischung, kein erfundener Wert',(){final lines=<Json>[{'quantity':1,'unit':'kg','costType':'Material','materialKind':'meat','analysis':{'fat':20,'meatProtein':16,'connectiveProtein':2}},{'quantity':1,'unit':'kg','costType':'Material','materialKind':'meat','analysis':{'fat':10,'meatProtein':20,'connectiveProtein':4}}];final a=rawAnalysis(lines);expect(a['fat'],15);expect(a['beffe'],15);expect(a['beffeRatio'],closeTo(83.33333,.0001));expect(a.containsKey('water'),false);lines.add({'quantity':1,'unit':'kg','costType':'Material','analysis':{}});expect(rawAnalysis(lines).containsKey('fat'),false);});
  test('Historische Regeln und fehlende Nachweise führen nicht zu bestanden',(){final reg={'id':'a','source':'Quelle','status':'Rechtsquelle'};final rule={'name':'Test','regulationId':'a','metric':'fat','basis':'Fertigprodukt','category':'Alle','max':30,'verified':true,'checkedOn':'2026-01-01','reviewer':'Fachperson','reference':'Testfundstelle','validFrom':'2026-01-01'};List<Json> run(Json source,List<Json> observations)=>evaluateRules(rules:[rule],regulations:[source],category:'Rohwurst',product:'Test',estimates:{'fat':10},observations:observations,date:'2026-11-24');expect(run(reg,[]).first['status'],'Wert fehlt');expect(run({...reg,'status':'Historisch'},[]).first['status'],'Regel nicht freigegeben');expect(run(reg,[{'metric':'fat','basis':'Fertigprodukt','value':20,'source':'Schätzung','reference':'x'}]).first['status'],'Mess-/Labornachweis fehlt');expect(run(reg,[{'metric':'fat','basis':'Fertigprodukt','value':40,'source':'Labor','reference':'x'}]).first['status'],'Grenzwertabweichung');});
  test('Spätere Verkäufe ergänzen den unveränderlichen Stand',(){final p=<String,dynamic>{'id':'p','soldKg':2,'summary':{'actualRevenue':20,'cost':100,'outputKg':12}};final sales=<Json>[{'productionId':'p','quantityKg':3,'priceNet':15},{'productionId':'other','quantityKg':9,'priceNet':100}];final t=salesTotals(p,sales);expect(t['quantityKg'],5);expect(t['remainingKg'],7);expect(t['revenue'],65);expect(t['balance'],-35);});
  test('Alle 15 Vorlagen sind leer und keine Regeln sind vorab freigegeben',(){final rows=seedRecords();final recipes=rows.where((r)=>r['kind']=='recipe').toList();expect(recipes.length,15);expect(recipes.every((r)=>maps(map(r['data'])['lines']).isEmpty),true);expect(rows.where((r)=>r['kind']=='rule'),isEmpty);});
}
